
let _quiet = false;
let _verbose = false;
let _debug = false;

// Internal stack to save log settings for nested calls
let logSettings: [boolean, boolean, boolean][] = [[false, false, false]];

/**
 * Sets the verbosity level for logging. If options are not provided, it will check the command-line arguments for --quiet, --verbose, and --debug flags.
 * 
 * Before changing the settings, the current settings are saved to an internal stack to allow for restoration later. This is useful for nested calls where different verbosity levels may be needed.
 */
export function verbosity(options?: { verbose?: boolean, quiet?: boolean, debug?: boolean }) {
    // Save the current settings to the stack
    logSettings.push([_quiet, _verbose, _debug]);
    if (!options) {
        _quiet = process.argv.includes("--quiet") || process.argv.includes("-q");
        _verbose = process.argv.includes("--verbose") || process.argv.includes("-v");
        _debug = process.argv.includes("--debug");
    } else {
        _quiet = !!options.quiet;
        _verbose = !!options.verbose;
        _debug = !!options.debug;
    }
}

/** 
 * Restores the previous verbosity settings from the internal stack if set. Otherwise, it does nothing.
 * 
 * Only if the stack contains more than one settings, the last setting is popped. That is, the root settings will not be popped.
 * @return true, if more settings were popped, false if the stack was already at the root settings and nothing was popped.
 */
export function restoreVerbosity() {
    const canPop = logSettings.length > 1;
    const [quiet, verbose, debug] = canPop ? logSettings.pop()! : logSettings.at(-1)!;
    _quiet = quiet;
    _verbose = verbose;
    _debug = debug;
    return canPop;
}

/**
 * Returns current settings of verbosity.
 */
export function getVerbosity() {
    return {
        quiet: _quiet,
        verbose: _verbose,
        debug: _debug
    };
}

export function error(msg: any) {
    console.error(msg);
    if (msg instanceof Error && _verbose) {
        console.error(msg.stack);
    }
}

export function warn(msg: any) {
    console.warn(msg);
}

export function verb(msg: any) {
    if (_verbose || _debug) {
        console.log(msg);
    }
}

export function debug(msg: any) {
    if (_debug) {
        console.debug(msg);
    }
}

export function log(msg: any) {
    if (!_quiet) {
        console.log(msg);
    }
}
